i","id":"UGVyc29uOm55dDovL3BlcnNvbi80NTZlNGUyMC0zZjc0LTU2OWEtOTc3Ni02MGY5YzIyNjE0NjE=","promotionalMedia":{"__typename":"Image","crops":[{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","name":"thumbLarge","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2018\\u002F02\\u002F20\\u002Fmultimedia\\u002Fauthor-sapna-maheshwari\\u002Fauthor-sapna-maheshwari-thumbLarge-v2.png"}]}],"id":"SW1hZ2U6bnl0Oi8vaW1hZ2UvOGFhNzA0YjctZDA4YS01MGJhLTgyM2ItYmVmMTUyMDNmNWQz"}}],"prefix":"By","renderedRepresentation":"By Sapna Maheshwari"}],"hideHeadshots":false,"role":[],"textAlign":"DEFAULT"},"headline":{"__typename":"Heading1Block","content":[{"__typename":"TextInline","formats":[],"text":"YouTube Kids, Criticized for Content, Introduces New Parental Controls"}],"textAlign":"DEFAULT"},"label":null,"ledeMedia":{"__typename":"ImageBlock","desktopCrop":null,"hasMobileSize":false,"media":{"__typename":"Image","altText":"","caption":{"__typename":"TextOnlyDocumentBlock","content":[{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"Some content that has slipped past filters on YouTube Kids, which is supposed to contain only child-friendly content, contains well-known characters in disturbing situations."}]}],"text":"Some content that has slipped past filters on YouTube Kids, which is supposed to contain only child-friendly content, contains well-known characters in disturbing situations."},"credit":"","crops":[{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":408,"name":"articleLarge","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS02-inyt\\u002F07YOUTUBEKIDS02-inyt-articleLarge.jpg","width":600},{"__typename":"ImageRendition","height":442,"name":"popup","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS02-inyt\\u002F07YOUTUBEKIDS02-inyt-popup.jpg","width":650},{"__typename":"ImageRendition","height":521,"name":"jumbo","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS02-inyt\\u002F07YOUTUBEKIDS02-inyt-jumbo.jpg","width":767},{"__typename":"ImageRendition","height":521,"name":"superJumbo","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS02-inyt\\u002F07YOUTUBEKIDS02-inyt-superJumbo.jpg","width":767}]},{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":150,"name":"thumbLarge","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS02-inyt\\u002F07YOUTUBEKIDS02-inyt-thumbLarge.jpg","width":150}]},{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":129,"name":"articleInline","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS02-inyt\\u002F07YOUTUBEKIDS02-inyt-articleInline.jpg","width":190}]}],"id":"SW1hZ2U6bnl0Oi8vaW1hZ2UvNWYxNGMwYTMtMjRjMy01M2NkLWE3MTItZTQ1MDI2ZDJmOGRj","imageType":"photo","legacyHtmlCaption":"Some content that has slipped past filters on YouTube Kids, which is supposed to contain only child-friendly content, contains well-known characters in disturbing situations.","timesTags":[],"uri":"nyt:\\u002F\\u002Fimage\\u002F5f14c0a3-24c3-53cd-a712-e45026d2f8dc","url":"https:\\u002F\\u002Fwww.nytimes.com\\u002Fimagepages\\u002F2018\\u002F04\\u002F25\\u002Fbusiness\\u002F07YOUTUBEKIDS02-inyt.html"},"mobileAltText":null,"mobileCaption":null,"mobileCredit":null,"mobileCrop":null,"mobileMedia":null,"mobileSize":null,"size":"MEDIUM"},"subhead":null,"timestampBlock":{"__typename":"TimestampBlock","align":"DEFAULT","showUpdatedTimestamp":null,"timestamp":"2018-04-25T19:00:04.000Z"}},{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"YouTube Kids, which has been criticized for inadvertently recommending disturbing videos to children, said Wednesday that it would introduce several ways for parents to limit what can be watched on the popular app."}],"textAlign":"DEFAULT"},{"__typename":"Dropzone","adsDesktop":false,"adsDesktopHoldout":false,"adsHybrid":false,"adsHybridHoldout":false,"adsMobile":false,"adsMobileHoldout":false,"bad":false,"index":0},{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"Beginning this week, parents will be able to select “trusted channels” and topics that their children can access on the app, like “Sesame Workshop” or “learning,” that have been curated by people at YouTube Kids and its partners. The Google-owned app said in a blog post on Wednesday that parents would also have the option to restrict video recommendations to channels that have been “verified” by YouTube Kids, avoiding the broader sea of content that the app pulls from the main YouTube site through algorithms and other automated processes."}],"textAlign":"DEFAULT"},{"__typename":"Dropzone","adsDesktop":false,"adsDesktopHoldout":false,"adsHybrid":false,"adsHybridHoldout":false,"adsMobile":false,"adsMobileHoldout":false,"bad":false,"index":1},{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"YouTube Kids was introduced in 2015 for children of preschool age and older, and it says it has more than 11 million weekly viewers. But parents have discovered a range of inappropriate videos on the app, highlighting the platform’s dependence on automation and a lack of human oversight. The New York Times "},{"__typename":"TextInline","formats":[{"__typename":"LinkFormat","title":"","uri":null,"url":"https:\\u002F\\u002Fwww.nytimes.com\\u002F2017\\u002F11\\u002F04\\u002Fbusiness\\u002Fmedia\\u002Fyoutube-kids-paw-patrol.html"}],"text":"reported in the fall"},{"__typename":"TextInline","formats":[],"text":" that children using the app had been shown videos with popular characters from Nick Jr. and Disney Junior in violent or lewd situations, and other disturbing imagery, sometimes set to nursery rhymes."}],"textAlign":"DEFAULT"},{"__typename":"Dropzone","adsDesktop":true,"adsDesktopHoldout":true,"adsHybrid":true,"adsHybridHoldout":true,"adsMobile":true,"adsMobileHoldout":true,"bad":false,"index":2},{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"More recently, "},{"__typename":"TextInline","formats":[{"__typename":"LinkFormat","title":"","uri":null,"url":"http:\\u002F\\u002Fwww.businessinsider.com\\u002Fyoutube-suggested-conspiracy-videos-to-children-using-its-kids-app-2018-3"}],"text":"Business Insider reported"},{"__typename":"TextInline","formats":[],"text":" that the app was suggesting conspiracy theory videos to children, including claims that the world is flat and that the moon landing was faked. YouTube Kids had previously relied primarily on parents to report troubling videos, a practice that was criticized because children are often the only ones watching the content on tablets or phones."}],"textAlign":"DEFAULT"},{"__typename":"Dropzone","adsDesktop":false,"adsDesktopHoldout":false,"adsHybrid":false,"adsHybridHoldout":false,"adsMobile":false,"adsMobileHoldout":false,"bad":true,"index":3},{"__typename":"ImageBlock","desktopCrop":null,"hasMobileSize":false,"media":{"__typename":"Image","altText":"","caption":{"__typename":"TextOnlyDocumentBlock","content":[{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"This video, which appeared on YouTube Kids, was uploaded by a verified account on YouTube called Freak Family and has attracted more than 20 million views."}]}],"text":"This video, which appeared on YouTube Kids, was uploaded by a verified account on YouTube called Freak Family and has attracted more than 20 million views."},"credit":"","crops":[{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":408,"name":"articleLarge","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS04-inyt\\u002F07YOUTUBEKIDS04-inyt-articleLarge.jpg","width":600},{"__typename":"ImageRendition","height":442,"name":"popup","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS04-inyt\\u002F07YOUTUBEKIDS04-inyt-popup.jpg","width":650},{"__typename":"ImageRendition","height":562,"name":"jumbo","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS04-inyt\\u002F07YOUTUBEKIDS04-inyt-jumbo.jpg","width":827},{"__typename":"ImageRendition","height":562,"name":"superJumbo","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS04-inyt\\u002F07YOUTUBEKIDS04-inyt-superJumbo.jpg","width":827}]},{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":150,"name":"thumbLarge","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS04-inyt\\u002F07YOUTUBEKIDS04-inyt-thumbLarge.jpg","width":150}]},{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":129,"name":"articleInline","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2017\\u002F11\\u002F07\\u002Fbusiness\\u002F07YOUTUBEKIDS04-inyt\\u002F07YOUTUBEKIDS04-inyt-articleInline.jpg","width":190}]}],"id":"SW1hZ2U6bnl0Oi8vaW1hZ2UvZTY5ZWI4OWEtMTIyZS01YzE3LWFiMTMtNDA0YmViY2MzZDU4","imageType":"photo","legacyHtmlCaption":"This video, which appeared on YouTube Kids, was uploaded by a verified account on YouTube called Freak Family and has attracted more than 20 million views.","timesTags":[],"uri":"nyt:\\u002F\\u002Fimage\\u002Fe69eb89a-122e-5c17-ab13-404bebcc3d58","url":"https:\\u002F\\u002Fwww.nytimes.com\\u002Fimagepages\\u002F2018\\u002F04\\u002F25\\u002Fbusiness\\u002F07YOUTUBEKIDS04-inyt.html"},"mobileAltText":null,"mobileCaption":null,"mobileCredit":null,"mobileCrop":null,"mobileMedia":null,"mobileSize":null,"size":"MEDIUM"},{"__typename":"Dropzone","adsDesktop":false,"adsDesktopHoldout":false,"adsHybrid":false,"adsHybridHoldout":false,"adsMobile":false,"adsMobileHoldout":false,"bad":true,"index":4},{"__typename":"ImageBlock","desktopCrop":null,"hasMobileSize":false,"media":{"__typename":"Image","altText":"","caption":{"__typename":"TextOnlyDocumentBlock","content":[{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"Parents will be able to limit access to videos from channels approved either by them or by the YouTube Kids team."}]}],"text":"Parents will be able to limit access to videos from channels approved either by them or by the YouTube Kids team."},"credit":"","crops":[{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":450,"name":"articleLarge","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2018\\u002F04\\u002F26\\u002Fbusiness\\u002F26YOUTUBE\\u002Fmerlin_137315502_6a3c4b11-7004-4cca-8658-ecd5c8286504-articleLarge.jpg","width":600},{"__typename":"ImageRendition","height":488,"name":"popup","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2018\\u002F04\\u002F26\\u002Fbusiness\\u002F26YOUTUBE\\u002Fmerlin_137315502_6a3c4b11-7004-4cca-8658-ecd5c8286504-popup.jpg","width":650},{"__typename":"ImageRendition","height":768,"name":"jumbo","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2018\\u002F04\\u002F26\\u002Fbusiness\\u002F26YOUTUBE\\u002Fmerlin_137315502_6a3c4b11-7004-4cca-8658-ecd5c8286504-jumbo.jpg","width":1024},{"__typename":"ImageRendition","height":900,"name":"superJumbo","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2018\\u002F04\\u002F26\\u002Fbusiness\\u002F26YOUTUBE\\u002Fmerlin_137315502_6a3c4b11-7004-4cca-8658-ecd5c8286504-superJumbo.jpg","width":1200}]},{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":150,"name":"thumbLarge","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2018\\u002F04\\u002F26\\u002Fbusiness\\u002F26YOUTUBE\\u002Fmerlin_137315502_6a3c4b11-7004-4cca-8658-ecd5c8286504-thumbLarge.jpg","width":150}]},{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":640,"name":"square640","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2018\\u002F04\\u002F26\\u002Fbusiness\\u002F26YOUTUBE\\u002Fmerlin_137315502_6a3c4b11-7004-4cca-8658-ecd5c8286504-square640.jpg","width":640}]},{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":800,"name":"threeByTwoLargeAt2X","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2018\\u002F04\\u002F26\\u002Fbusiness\\u002F26YOUTUBE\\u002Fmerlin_137315502_6a3c4b11-7004-4cca-8658-ecd5c8286504-threeByTwoLargeAt2X.jpg","width":1200},{"__typename":"ImageRendition","height":400,"name":"threeByTwoSmallAt2X","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2018\\u002F04\\u002F26\\u002Fbusiness\\u002F26YOUTUBE\\u002Fmerlin_137315502_6a3c4b11-7004-4cca-8658-ecd5c8286504-threeByTwoSmallAt2X.jpg","width":600}]},{"__typename":"ImageCrop","renditions":[{"__typename":"ImageRendition","height":143,"name":"articleInline","url":"https:\\u002F\\u002Fstatic01.nyt.com\\u002Fimages\\u002F2018\\u002F04\\u002F26\\u002Fbusiness\\u002F26YOUTUBE\\u002Fmerlin_137315502_6a3c4b11-7004-4cca-8658-ecd5c8286504-articleInline.jpg","width":190}]}],"id":"SW1hZ2U6bnl0Oi8vaW1hZ2UvZWQwOGQ3YWQtOTA0Mi01MWU5LTk2YzctZWMwZWQ1ZDk3NmZi","imageType":"photo","legacyHtmlCaption":"Parents will be able to limit access to videos from channels approved either by them or by the YouTube Kids team.","timesTags":[],"uri":"nyt:\\u002F\\u002Fimage\\u002Fed08d7ad-9042-51e9-96c7-ec0ed5d976fb","url":"https:\\u002F\\u002Fwww.nytimes.com\\u002Fimagepages\\u002F2018\\u002F04\\u002F25\\u002Fbusiness\\u002F26YOUTUBE.html"},"mobileAltText":null,"mobileCaption":null,"mobileCredit":null,"mobileCrop":null,"mobileMedia":null,"mobileSize":null,"size":"MEDIUM"},{"__typename":"Dropzone","adsDesktop":false,"adsDesktopHoldout":false,"adsHybrid":false,"adsHybridHoldout":false,"adsMobile":false,"adsMobileHoldout":false,"bad":true,"index":5},{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"Later this year, parents will be able to handpick every video and channel that children can view through the app, YouTube Kids said in its blog post, even restricting them to, say, 10 videos or a single channel."}],"textAlign":"DEFAULT"},{"__typename":"Dropzone","adsDesktop":false,"adsDesktopHoldout":false,"adsHybrid":false,"adsHybridHoldout":false,"adsMobile":false,"adsMobileHoldout":false,"bad":false,"index":6},{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"The changes announced Wednesday provide “a more robust suite of tools for parents to customize the YouTube Kids experience,” James Beser, product director for the platform, said in a statement. “From collections of channels from trusted partners to enabling parents to select each video and channel themselves, we’re putting parents in the driver’s seat like never before.”"}],"textAlign":"DEFAULT"},{"__typename":"Dropzone","adsDesktop":false,"adsDesktopHoldout":false,"adsHybrid":true,"adsHybridHoldout":true,"adsMobile":true,"adsMobileHoldout":true,"bad":false,"index":7},{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"The announcement is part of a broader conversation around how Google, the world’s biggest seller of digital advertising, uses human oversight for the enormous volume of content on YouTube. CNN "},{"__typename":"TextInline","formats":[{"__typename":"LinkFormat","title":"","uri":null,"url":"http:\\u002F\\u002Fmoney.cnn.com\\u002F2018\\u002F04\\u002F19\\u002Ftechnology\\u002Fyoutube-ads-extreme-content-investigation\\u002Findex.html"}],"text":"recently"},{"__typename":"TextInline","formats":[],"text":" found hundreds of advertisers, including The Times, on inappropriate YouTube channels promoting conspiracies, white nationalism and pedophilia. YouTube "},{"__typename":"TextInline","formats":[{"__typename":"LinkFormat","title":"","uri":null,"url":"https:\\u002F\\u002Fwww.nytimes.com\\u002F2018\\u002F01\\u002F16\\u002Ftechnology\\u002Fyoutube-ads-scrutiny.html"}],"text":"has said"},{"__typename":"TextInline","formats":[],"text":" it will be using more human reviewers, particularly with Google Preferred, a grouping of top-tier videos on the site that helps brands advertise on popular videos."}],"textAlign":"DEFAULT"},{"__typename":"Dropzone","adsDesktop":true,"adsDesktopHoldout":true,"adsHybrid":false,"adsHybridHoldout":false,"adsMobile":false,"adsMobileHoldout":false,"bad":false,"index":8},{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"YouTube has faced other issues around children. This month, a coalition of consumer advocacy groups "},{"__typename":"TextInline","formats":[{"__typename":"LinkFormat","title":"","uri":null,"url":"https:\\u002F\\u002Fwww.nytimes.com\\u002F2018\\u002F04\\u002F09\\u002Fbusiness\\u002Fmedia\\u002Fyoutube-kids-ftc-complaint.html"}],"text":"contended that YouTube"},{"__typename":"TextInline","formats":[],"text":" had been aware that children 12 and younger have been watching the main site and that, therefore, it had been violating a privacy law that requires parental consent before collecting and mining their data. Google assumes that viewers on the main YouTube site and app are at least 13 years old, which enables the company to collect certain information from those users and serve them personalized ads."}],"textAlign":"DEFAULT"},{"__typename":"Dropzone","adsDesktop":false,"adsDesktopHoldout":false,"adsHybrid":false,"adsHybridHoldout":false,"adsMobile":false,"adsMobileHoldout":false,"bad":false,"index":9},{"__typename":"ParagraphBlock","content":[{"__typename":"TextInline","formats":[],"text":"YouTube said it planned to read the complaint “thoroughly” but noted that “because YouTube is not for children, we’ve invested significantly in the creation of the YouTube Kids app to offer an alternative specifically designed for children.”"}],"textAlign":"DEFAULT"}]},"storyFormat":null,"storylines":[{"__typename":"AssociatedStoryline","ruleName":"styln-media","storyline":{"__typename":"Storyline","context":null,"displayName":"Media","experimentalJsonBlob":"{\\"data\\":[{\\"version\\":1,\\"type\\":\\"experimentalJsonBlob\\",\\"data\\":[]}]}","hubAssets":[],"primaryAssets":[],"promotedLiveAssets":[],"tone":"NEWS","topLinks":null,"uri":"nyt:\\u002F\\u002Fstoryline\\u002F403b31f6-7d33-4eb2-b45c-a1a8aff288ac","url":"https:\\u002F\\u002Fwww.nytimes.com\\u002Fstoryline\\u002F403b31f6-7d33-4eb2-b45c-a1a8aff288ac"},"testName":""},{"__typename":"AssociatedStoryline","ruleName":"styln-business-general","storyline":{"__typename":"Storyline","context":null,"displayName":"Best of Business","experimentalJsonBlob":"{\\"data\\":[{\\"version\\":1,\\"type\\":\\"experimentalJsonBlob\\",\\"data\\":[]}]}","hubAssets":[],"primaryAssets":[],"promotedLiveAssets":[],"tone":"NEWS","topLinks":null,"uri":"nyt:\\u002F\\u002Fstoryline\\u002F3ef25df1-b742-4684-8f0a-fae77b4d2826","url":"https:\\u002F\\u002Fwww.nytimes.com\\u002Fstoryline\\u002F3ef25df1-b742-4684-8f0a-fae77b4d2826"},"testName":""}],"subsection":{"__typename":"Section","displayName":"Media","id":"U2VjdGlvbjpueXQ6Ly9zZWN0aW9uL2ZhMWM2YzRhLWFjOTYtNWZiZi1iMTdiLTRhYTllMTlhNzljYg==","name":"media","uri":"nyt:\\u002F\\u002Fsection\\u002Ffa1c6c4a-ac96-5fbf-b17b-4aa9e19a79cb","url":""},"summary":"Parents will be able to handpick the channels and topics their children can view on the app, which has been criticized for allowing disturbing content to slip through.","timesTags":[{"__typename":"Subject","associatedLegacyCollections":[],"displayName":"Children and Childhood","isAdver